package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class EvidenceSessionApiTest {
 EvidenceSessionStore store;SpaceAuthorizationClient auth;EvidenceSessionController api;UUID space,roadmap,evidence,actor,session;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();roadmap=ids.next();evidence=ids.next();actor=ids.next();session=ids.next();store=mock(EvidenceSessionStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);var metrics=new SimpleMeterRegistry();api=new EvidenceSessionController(store,new RoadmapController(mock(RoadmapStore.class),auth,metrics,"https://localhost:8443"),metrics);}
 MockHttpServletRequest r(String method,String body,String tag){var r=new MockHttpServletRequest(method,"/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(tag!=null)r.addHeader("If-Match",tag);if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void eachTypedRouteFreshlyAuthorizesAndDenialPreventsCanonicalAccess(){when(store.history(space,roadmap,evidence,"NOTE",Long.MAX_VALUE,5)).thenReturn(List.of());api.history(space.toString(),roadmap.toString(),"evidence",evidence.toString(),r("GET",null,null));api.history(space.toString(),roadmap.toString(),"evidence",evidence.toString(),r("GET",null,null));verify(auth,times(2)).authorize(eq(space),any(),eq(false),anyString());reset(store);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),roadmap.toString(),"media-evidence",evidence.toString(),r("GET",null,null)));verifyNoInteractions(store);assertEquals("CONCEPT",EvidenceSessionController.kind("concept-evidence"));assertThrows(ResponseStatusException.class,()->EvidenceSessionController.kind("unknown"));}
 @Test void independentStrongEtagStrictBodiesAndOriginAreRequired()throws Exception{String valid="{\"sessionId\":\""+session+"\",\"sessionVersion\":1}";for(String tag:List.of("\"ev1\"","\"ss1\"","\"es01\"","W/\"es1\"","*"))assertThrows(ResponseStatusException.class,()->api.change(space.toString(),roadmap.toString(),"evidence",evidence.toString(),r("PUT",valid,tag)));assertEquals(428,assertThrows(ResponseStatusException.class,()->api.change(space.toString(),roadmap.toString(),"evidence",evidence.toString(),r("PUT",valid,null))).getStatusCode().value());for(String body:List.of("{}",valid+" {}",valid.replace(":1",":1.5"),"{\"sessionId\":null,\"sessionVersion\":null,\"sessionVersion\":null}"))assertThrows(ResponseStatusException.class,()->api.change(space.toString(),roadmap.toString(),"evidence",evidence.toString(),r("PUT",body,"\"es0\"")));var cross=r("PUT",valid,"\"es0\"");cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.change(space.toString(),roadmap.toString(),"evidence",evidence.toString(),cross)).getStatusCode().value());verifyNoInteractions(store);}
 @Test void readsRejectUnknownRepeatedAndOutOfRangeQueryParameters(){var q=r("GET",null,null);q.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.history(space.toString(),roadmap.toString(),"evidence",evidence.toString(),q));var u=r("GET",null,null);u.addParameter("sessionId",session.toString());assertThrows(ResponseStatusException.class,()->api.get(space.toString(),roadmap.toString(),"evidence",evidence.toString(),u));verifyNoInteractions(store);}
}
